\subsection{Problem Formulation for Online Assignment}\label{sec:PFormulation}

There are $m$ resources and the initial capacity of each resource is scaled to $1$. At each period $t$, query $t$ arrives and is associated with a non-negative reward $\mathbf{\tilde{r}}_t=(\tilde{r}_{t1},\dots,\tilde{r}_{tm})$ and a size $\mathbf{\tilde{d}}_t=(\tilde{d}_{t1},\dots,\tilde{d}_{tm})\in(0,1]^m$, where vector $(\mathbf{\tilde{r}}_t, \mathbf{\tilde{d}}_t)$ is assumed to be stochastic and drawn from a known distribution $F_t(\cdot)$. 

\subsection{Improvement in the Unit-density Special Case} \label{sec:unitDensity}

In this section, we consider the unit-density special case of our online knapsack problem where $\tilde{r}_t=\tilde{d}_t$ for each $t$. Then we can suppress the notation $(\tilde{r}_t, \tilde{d}_t)$ and simply use $\tilde{d}_t$ to denote the size and the reward of query $t$. 

\begin{algorithm}
\caption{Pre-processed algorithm for the knapsack OCRS problem ($\pi_{\gamma}$)}
\begin{algorithmic}[1]
\State \textbf{Input}: a parameter $\gamma$ and the sequence of probabilities $\{p_t(d_t), \forall t, \forall d_t\}$ satisfying $\sum_t \sum_{d_t} p_t(d_t)\cdot d_t\leq 1$ and $\sum_{d_t} p_t(d_t)\le 1$ for each $t$.
\State We initialize $\tilde{X}_{0,\gamma}$ as a random variable that takes the value $0$ deterministically.
\For{$t=1,2,\dots,T$,}
\State For each realization $d_t>0$, we denote a threshold $\eta_{t,\gamma}(d_t)$ satisfying:
        \begin{equation}\label{defineetarandomsize}
        P(\eta_{t,\gamma}(d_t)<\tilde{X}_{t-1,\gamma}\leq1-d_t)\leq\gamma\leq P(\eta_{t,\gamma}(d_t)\leq\tilde{X}_{t-1,\gamma}\leq1-d_t).
        \end{equation}
\State Initialize $\tilde{X}_{t, \gamma}$ as $\tilde{X}_{t-1, \gamma}$. We now update $\tilde{X}_{t, \gamma}$ to reflect the distribution of the capacity utilization at the end of period $t-1$ via the following procedures. We first let the distribution of $\tilde{X}_{t, \gamma}$ be identical to $\tilde{X}_{t-1,\gamma}$. Then, for each size realization $d_t>0$ and each point $x\in (\eta_{t,\gamma}(d_t) ,1-d_t]$, we decrease the probability of $P(\tilde{X}_{t, \gamma}=x)$ by $p_t(d_t)\cdot P(\tilde{X}_{t-1,\gamma}=x)$ and increase the probability of $P(\tilde{X}_{t, \gamma}=x+d_t)$ by $p_t(d_t)\cdot P(\tilde{X}_{t-1,\gamma}=x)$. For each size realization $d_t$ and $x=\eta_{t,\gamma}(d_t)$, we decrease the probability of $P(\tilde{X}_{t, \gamma}=x)$ by $p_t(d_t)\cdot(\gamma-P(\eta_{t,\gamma}(d_t)<\tilde{X}_{t-1,\gamma}\leq1-d_t))$ and increase the probability of $P(\tilde{X}_{t, \gamma}=x+d_t)$ by $p_t(d_t)\cdot(\gamma-P(\eta_{t,\gamma}(d_t)<\tilde{X}_{t-1,\gamma}\leq1-d_t))$.\label{Updaterandomdistribution}
\EndFor
\State \textbf{Output}: the distributions $\{\tilde{X}_{t,\gamma}, \forall t\}$ and the thresholds $\{ \eta_{t, \gamma}(d_t), \forall t, \forall d_t \}$. 
\end{algorithmic}
\label{definedistributionrandomsize}
\end{algorithm}

For any $a$ and $b$, denote $\mu_{t,\gamma}(a,b]=P(a<\tilde{X}_{t,\gamma}\leq b)$ assuming $\tilde{X}_{t,\gamma}$ is well defined.

\begin{lemma}\label{generalsamplepathlemma}
For any $0<b\leq\frac{1}{2}$ and any $0<\gamma<1$ such that $\tilde{X}_{t,\gamma}$ is well-defined in that $\eta_{t,\gamma}(d_t)$ exists for all possible sizes $d_t$, the following inequality
\begin{equation}\label{generalsamplepathinequality}
\frac{1}{\gamma}\cdot\mu_{t,\gamma}(0,b]\leq\exp(-\frac{1}{\gamma}\cdot\mu_{t,\gamma}(b,1-b])
\end{equation}
holds for all $t=0,1,\dots,T$.
\end{lemma}

\begin{algorithm}
\caption{Pre-processed algorithm for unit-density special case}
\begin{algorithmic}[1]
\State Input: a sequence $\boldsymbol{\gamma}$ satisfying $1\geq\gamma_1\geq\gamma_2\geq\dots\geq\gamma_T\geq0$ and a sequence of probabilities $\{p_t(d_t), \forall t,\forall d_t\}$ satisfying $\sum_t \sum_{d_t} p_t(d_t)\cdot d_t\leq 1$ and $\sum_{d_t} p_t(d_t)$ for each $t$
\State We initialize $\tilde{X}_{0,\boldsymbol{\gamma}}$ as a random variable taking value $0$ with probability $1$.
\For{$t=1,2,\dots,T$}
For each realization $d_t>0$, we denote a threshold $\eta_{t,\boldsymbol{\gamma}}(d_t)$ satisfying
        \begin{equation}\label{defineetaUD}
        P(\eta_{t,\boldsymbol{\gamma}}(d_t)<\tilde{X}_{t-1,\boldsymbol{\gamma}}\leq1-d_t)\leq\gamma_t\leq P(\eta_{t,\boldsymbol{\gamma}}(d_t)\leq\tilde{X}_{t-1,\boldsymbol{\gamma}}\leq1-d_t).
        \end{equation}
\State Initialize $\tilde{X}_{t, \boldsymbol{\gamma}}$ as $\tilde{X}_{t-1, \boldsymbol{\gamma}}$. We now update $\tilde{X}_{t, \boldsymbol{\gamma}}$ to reflect the distribution of the capacity utilization at the end of period $t-1$ via the following procedures. We first let the distribution of $\tilde{X}_{t, \boldsymbol{\gamma}}$ be identical to $\tilde{X}_{t-1,\boldsymbol{\gamma}}$. Then, for each size realization $d_t>0$ and each point $x\in (\eta_{t,\boldsymbol{\gamma}}(d_t) ,1-d_t]$, we decrease the probability of $P(\tilde{X}_{t, \boldsymbol{\gamma}}=x)$ by $p_t(d_t)\cdot P(\tilde{X}_{t-1,\boldsymbol{\gamma}}=x)$ and increase the probability of $P(\tilde{X}_{t, \boldsymbol{\gamma}}=x+d_t)$ by $p_t(d_t)\cdot P(\tilde{X}_{t-1,\boldsymbol{\gamma}}=x)$. For each size realization $d_t>0$ and $x=\eta_{t,\boldsymbol{\gamma}}(d_t)$, we decrease the probability of $P(\tilde{X}_{t, \boldsymbol{\gamma}}=x)$ by $p_t(d_t)\cdot(\gamma_t-P(\eta_{t,\boldsymbol{\gamma}}(d_t)<\tilde{X}_{t-1,\boldsymbol{\gamma}}\leq1-d_t))$ and increase the probability of $P(\tilde{X}_{t, \boldsymbol{\gamma}}=x+d_t)$ by $p_t(d_t)\cdot(\gamma_t-P(\eta_{t,\boldsymbol{\gamma}}(d_t)<\tilde{X}_{t-1,\boldsymbol{\gamma}}\leq1-d_t))$.
\EndFor
\State Output: the distributions $\{\tilde{X}_{t,\bm{\gamma}}, \forall t\}$ and the thresholds $\{ \eta_{t, \bm{\gamma}}(d_t), \forall t, \forall d_t \}$. 
\end{algorithmic}
\label{UDpolicy}
\end{algorithm}
